def grade(score):
    passed = score >= 50
    if passed:
        return 'pass'
    return 'fail'

def apply_fee(amount, vip):
    fee = 5
    if vip:
        fee = 0
    return amount + fee

def ship(weight, express):
    cost = 5
    if weight > 100:
        cost = 20
        if express:
            cost += 15
    return cost
